class File {                                // owner: no public close()
public:
    explicit File(const char* p) : f_(std::fopen(p, "rb")) {
        if (!f_) throw std::runtime_error("open failed");  // no half-open state
    }
    ~File() { if (f_) std::fclose(f_); }    // non-throwing, exactly once
    File(File&& o) noexcept : f_(o.f_) { o.f_ = nullptr; }
    File(const File&) = delete;             // copying would double-release
    std::FILE* get() const noexcept { return f_; }
private:
    std::FILE* f_;
};

