struct Fclose { void operator()(std::FILE* f) const noexcept { if (f) std::fclose(f); } };
using FilePtr = std::unique_ptr<std::FILE, Fclose>;

FilePtr open(const char* path) {
    if (auto* f = std::fopen(path, "rb")) return FilePtr{f};
    throw std::runtime_error("open failed");   // nothing to release
}
